const a=[{titulo:"Oficina Bate Lata",badge:"Projeto ativo",classeBadge:"badge-ativo",descricao:"Oficinas de percussão que utilizam instrumentos produzidos com latas de tinta reaproveitadas, proporcionando às crianças o contato com a música de forma criativa, acessível e sustentável."},{titulo:"Música que Ensina",badge:"",classeBadge:"",descricao:"Projeto que utiliza a música como ferramenta de aprendizagem, trabalhando conceitos de matemática, ritmo, contagem e raciocínio de maneira prática e divertida."},{titulo:"Lata que Transforma",badge:"",classeBadge:"",descricao:"Iniciativa voltada à coleta e ao reaproveitamento de latas de tinta, transformando materiais que seriam descartados em instrumentos musicais e promovendo a consciência ambiental."},{titulo:"Voluntariado",badge:"Voluntariado",classeBadge:"badge-voluntariado",descricao:"Os voluntários da Bate Lata podem participar das oficinas de percussão, auxiliar na organização das atividades e colaborar com as ações educativas desenvolvidas pela ONG.",link:"#cadastro",textoLink:"Quero ser voluntário"},{titulo:"Doações",badge:"Doações",classeBadge:"badge-doacao",descricao:"As doações ajudam a Bate Lata a manter suas oficinas e projetos sociais, contribuindo para a aquisição de baquetas, materiais para adaptação dos instrumentos e outros recursos utilizados nas atividades com as crianças.",link:"#cadastro",textoLink:"Quero contribuir"}];export function templateInicio(){return'\n    <section class="col-12">\n      <h2>Quem somos</h2>\n\n      <img\n        src="imagens/batelata1.webp"\n        alt="Crianças participando de uma oficina de percussão com instrumentos feitos de latas reaproveitadas"\n      />\n\n      <p>\n        A Bate Lata é uma organização que acredita no poder da música como\n        ferramenta de transformação social e educação. Reaproveitamos latas de\n        tinta que seriam descartadas e as transformamos em instrumentos de\n        percussão, proporcionando a crianças em situação de vulnerabilidade\n        social a oportunidade de aprender e vivenciar a música. Além da\n        educação musical, nossas atividades contribuem para o desenvolvimento\n        de outros conhecimentos, como a matemática, explorada de forma prática\n        por meio do ritmo e da contagem musical. Dessa forma, unimos educação,\n        cultura, inclusão social e consciência ambiental, transformando\n        materiais que seriam descartados em novas possibilidades para o futuro.\n      </p>\n    </section>\n\n    <section class="col-12">\n      <h2>Nossa missão</h2>\n\n      <p>\n        Nossa missão é promover inclusão social e desenvolvimento educacional\n        por meio da música, unindo criatividade, sustentabilidade e\n        aprendizado prático para transformar realidades.\n      </p>\n    </section>\n\n    <section class="col-12">\n      <h2>Contato</h2>\n\n      <p>E-mail: contato@batelata.org.br</p>\n      <p>Telefone: (11) 99999-9999</p>\n    </section>\n  '}export function templateProjetos(){return`\n    <section class="col-12 projetos-grid">\n      <h2>Projetos</h2>\n\n      <div class="alerta alerta-info" role="alert">\n        <strong>Novidade!</strong>\n        As inscrições para participar das oficinas e ações voluntárias estão abertas.\n      </div>\n\n      <button\n        type="button"\n        class="abrir-modal"\n        id="abrir-modal"\n      >\n        Como posso ajudar?\n      </button>\n\n      <div\n        class="modal"\n        id="modal-ajuda"\n        role="dialog"\n        aria-modal="true"\n        aria-labelledby="titulo-modal"\n        hidden\n      >\n        <div class="modal-conteudo">\n          <h3 id="titulo-modal">Como ajudar a Bate Lata</h3>\n\n          <p>\n            Você pode contribuir participando como voluntário, realizando doações\n            ou apoiando as atividades e oficinas desenvolvidas pela ONG.\n          </p>\n\n          <button type="button" id="fechar-modal">\n            Fechar\n          </button>\n        </div>\n      </div>\n\n      ${a.map(function(a){return function(a){return`\n    <article>\n      <h3>${a.titulo}</h3>\n\n      ${a.badge?`<span class="badge ${a.classeBadge}">${a.badge}</span>`:""}\n\n      <p>${a.descricao}</p>\n\n      ${a.link?`<a href="${a.link}" data-pagina="cadastro">\n              ${a.textoLink}\n            </a>`:""}\n    </article>\n  `}(a)}).join("")}\n    </section>\n  `}export function templateCadastro(){return'\n    <h2 class="col-12">Cadastro de participação</h2>\n\n    <form class="col-12" id="form-cadastro">\n      <p id="campos-obrigatorios">\n        Os campos marcados com * são obrigatórios.\n      </p>\n\n      <fieldset>\n        <legend>Dados pessoais</legend>\n\n        <label for="nome">Nome: *</label>\n        <input\n          type="text"\n          id="nome"\n          name="nome"\n          autocomplete="name"\n          required\n        />\n\n        <label for="email">E-mail: *</label>\n        <input\n          type="email"\n          id="email"\n          name="email"\n          autocomplete="email"\n          required\n        />\n\n        <label for="telefone">Telefone: *</label>\n        <input\n          type="tel"\n          id="telefone"\n          name="telefone"\n          autocomplete="tel"\n          required\n          maxlength="15"\n          pattern="\\([0-9]{2}\\) [0-9]{4,5}-[0-9]{4}"\n          placeholder="(00) 00000-0000"\n          aria-describedby="ajuda-telefone"\n        />\n        <small id="ajuda-telefone">Formato: (00) 00000-0000</small>\n\n        <label for="nascimento">Data de nascimento: *</label>\n        <input\n          type="date"\n          id="nascimento"\n          name="nascimento"\n          autocomplete="bday"\n          required\n        />\n\n        <label for="cpf">CPF: *</label>\n        <input\n          type="text"\n          id="cpf"\n          name="cpf"\n          required\n          maxlength="14"\n          pattern="[0-9]{3}\\.[0-9]{3}\\.[0-9]{3}-[0-9]{2}"\n          placeholder="000.000.000-00"\n          aria-describedby="ajuda-cpf"\n        />\n        <small id="ajuda-cpf">Formato: 000.000.000-00</small>\n      </fieldset>\n\n      <fieldset>\n        <legend>Endereço</legend>\n\n        <label for="cep">CEP: *</label>\n        <input\n          type="text"\n          id="cep"\n          name="cep"\n          autocomplete="postal-code"\n          required\n          maxlength="9"\n          pattern="[0-9]{5}-[0-9]{3}"\n          placeholder="00000-000"\n          aria-describedby="ajuda-cep"\n        />\n        <small id="ajuda-cep">Formato: 00000-000</small>\n\n        <label for="endereco">Endereço: *</label>\n        <input\n          type="text"\n          id="endereco"\n          name="endereco"\n          autocomplete="street-address"\n          required\n        />\n      </fieldset>\n\n      <fieldset>\n        <legend>Participação</legend>\n\n        <label for="participacao">Tipo de participação: *</label>\n        <select name="participacao" id="participacao" required>\n          <option value="">Selecione</option>\n          <option value="doador">Doador</option>\n          <option value="parceiro">Parceiro</option>\n          <option value="voluntario">Voluntário</option>\n        </select>\n\n        <label for="observacoes">Observações:</label>\n\n        <textarea\n          name="observacoes"\n          id="observacoes"\n        ></textarea>\n\n        <button type="submit">Enviar cadastro</button>\n\n        <p id="mensagem-formulario" aria-live="polite"></p>\n      </fieldset>\n    </form>\n  '}